(() => {
  const dialog = document.querySelector('[role="dialog"]') || document.querySelector('dialog');
  const buttons = Array.from(dialog ? dialog.querySelectorAll('button') : document.querySelectorAll('button'));
  return buttons.map(b => ({ text: b.textContent.trim(), outer: b.outerHTML, parent: b.parentElement.outerHTML }));
})()
